import{at as e,it as t,t as n,vt as r}from"./chunks/framework.CXXr-9tD.js";var i=JSON.parse(`{"title":"Sticky layers","description":"","frontmatter":{},"headers":[],"relativePath":"sticky.md","filePath":"pages/sticky.md"}`),a={name:`sticky.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="sticky-layers" tabindex="-1">Sticky layers <a class="header-anchor" href="#sticky-layers" aria-label="Permalink to “Sticky layers”">​</a></h1><ul><li><a href="#two-layers-one-idea">Two layers, one idea</a></li><li><a href="#column-header-ribbon">Column header ribbon</a></li><li><a href="#nested-group-stack">Nested group stack</a></li></ul><h2 id="two-layers-one-idea" tabindex="-1">Two layers, one idea <a class="header-anchor" href="#two-layers-one-idea" aria-label="Permalink to “Two layers, one idea”">​</a></h2><p>A tall diagram scrolls; the headers that label its columns and groups should not. grapht pins two kinds of header in screen space, both pure functions of the camera:</p><table tabindex="0"><thead><tr><th>layer</th><th>source</th><th>pins</th></tr></thead><tbody><tr><td><code>layoutStickyRibbon</code></td><td><code>packages/grapht-model/src/5a_stickyRibbon.ts:34</code></td><td>column headers in one horizontal row</td></tr><tr><td><code>stackGroupHeaders</code></td><td><code>packages/grapht/src/2_graph/6_stackGroupHeaders.ts:34</code></td><td>nested group headers in a vertical stack</td></tr></tbody></table><p>Neither mutates the graph or the camera. Each takes the camera and returns placements.</p><h2 id="column-header-ribbon" tabindex="-1">Column header ribbon <a class="header-anchor" href="#column-header-ribbon" aria-label="Permalink to “Column header ribbon”">​</a></h2><p><code>layoutStickyRibbon</code> places sequence actors as column headers in a screen-space row that survives pan and zoom. A header follows its column until the column leaves the viewport sideways or shrinks below <code>fullWidth</code>, then it condenses to a chip and clamps to the edge it left through.</p><table tabindex="0"><thead><tr><th>input</th><th>meaning</th></tr></thead><tbody><tr><td><code>camera</code></td><td>pan and zoom, in the <a href="./frame">frame</a> convention</td></tr><tr><td><code>viewport</code></td><td>the visible window, in screen space</td></tr><tr><td><code>inset</code></td><td>distance from the viewport edge to the row</td></tr><tr><td><code>fullWidth</code></td><td>below this a header renders as a <code>chip</code>, not <code>full</code></td></tr><tr><td><code>chipWidth</code></td><td>the width a condensed header takes</td></tr><tr><td><code>gap</code></td><td>space between consecutive headers</td></tr></tbody></table><p>Each <code>RibbonPlacement</code> carries one <code>state</code> and one <code>detail</code> (<code>packages/grapht-model/src/5a_stickyRibbon.ts:10</code>).</p><table tabindex="0"><thead><tr><th>state</th><th>when</th></tr></thead><tbody><tr><td><code>pinned</code></td><td>the header sits at its natural position inside the row</td></tr><tr><td><code>clamped-start</code></td><td>the column left through the left edge; the chip hugs it</td></tr><tr><td><code>clamped-end</code></td><td>the column left through the right edge; the chip hugs it</td></tr><tr><td><code>released</code></td><td>the column is fully offscreen vertically, or the row ran out of room</td></tr></tbody></table><p>The transition rule is at <code>packages/grapht-model/src/5a_stickyRibbon.ts:56</code>: a header is <code>clamped-start</code> when its natural left falls before the row start, <code>clamped-end</code> when it passes the row end, and <code>pinned</code> otherwise. A header too wide to fit the remaining row is released (<code>packages/grapht-model/src/5a_stickyRibbon.ts:58</code>), so a dense diagram drops the furthest headers instead of overlapping them.</p><h2 id="nested-group-stack" tabindex="-1">Nested group stack <a class="header-anchor" href="#nested-group-stack" aria-label="Permalink to “Nested group stack”">​</a></h2><p><code>stackGroupHeaders</code> stacks group headers along the top, parent above child, and swaps which header is stuck as you scroll through a group&#39;s band. The depth comes from the graph&#39;s own ancestry, not from geometry.</p><p>The stack walks the header families in graph order, and each family computes a slot below its stuck parent (<code>src/2_graph/6_stackGroupHeaders.ts:60</code>). Within a family, the header whose band currently contains the slot is the active one.</p><table tabindex="0"><thead><tr><th><code>HeaderPlacement.state</code></th><th>when</th><th>declared at</th></tr></thead><tbody><tr><td><code>stuck</code></td><td>this header is the active one in its family, pinned at the slot</td><td><code>src/2_graph/6_stackGroupHeaders.ts:86</code></td></tr><tr><td><code>natural</code></td><td>the header sits where the graph places it</td><td><code>src/2_graph/6_stackGroupHeaders.ts:87</code></td></tr><tr><td><code>released</code></td><td>the header&#39;s band is above the slot, replaced by a deeper one</td><td><code>src/2_graph/6_stackGroupHeaders.ts:87</code></td></tr></tbody></table><p>A header whose parent is hidden is itself hidden (<code>src/2_graph/6_stackGroupHeaders.ts:79</code>), so collapsing a group takes its whole stack with it. <code>HeaderPlacement</code> itself is declared at <code>packages/grapht/src/2_graph/0_frame.ts:23</code>.</p>`,17)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};